import java.io.InputStream;

public class ProblemE {
    public static long M = 998244353L;

    static class FastScanner {
        private final InputStream in = System.in;

        private int read() {
            try {
                return in.read();
            } catch (java.io.IOException e) {
                throw new RuntimeException(e);
            }
        }

        private boolean space(int c) {
            return c == -1 || Character.isWhitespace((char) c);
        }

        long nextLong() {
            int c = read();
            while (c != -1 && space(c)) c = read();
            if (c == -1) throw new java.util.NoSuchElementException();
            int sign = 1;
            if (c == '-' || c == '+') {
                if (c == '-') sign = -1;
                c = read();
            }
            long x = 0;
            while (c != -1 && !space(c)) {
                if (c < '0' || c > '9') throw new NumberFormatException();
                x = x * 10 + (c - '0');
                c = read();
            }
            return x * sign;
        }
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        long m = fs.nextLong();
        long n = fs.nextLong();
        long l = fs.nextLong();
        long r = fs.nextLong();

        long T = m * n;
        long num = r - l + 1;
        long a = exp(num, T);
        long inv2 = (M + 1) / 2;

        if (T % 2 == 1) {
            System.out.println(a);
        } else if (num % 2 == 0) {
            System.out.println((a * inv2) % M);
        } else {
            System.out.println(((a + 1) % M * inv2) % M);
        }
    }

    public static long exp(long a, long b) {
        if (b == 0) return 1;
        if (b == 1) return a;
        if (a == 1) return 1;
        if (b % 2 == 0) return exp((a * a) % M, b / 2);
        return (exp((a * a) % M, b / 2) * a) % M;
    }
}
